import type { Scenario, Scene } from '../types';
import { largeAdventure, largeEnd, largeScene, largeTags } from './largeContentTools';

const s = (id: string, title: string, text: string, choices: Scene['choices']) => largeScene(id, title, text, choices);
const end = (id: string, title: string, text: string, ending: 'success' | 'death' = 'success') => largeEnd(id, title, text, ending);
const fieldTags = (hook: string, setting: string, risk: 'LOW' | 'MODERATE' | 'HIGH', activity = 'labor/repair') =>
  largeTags({ hook, role: 'traveler/passenger', activity, tone: risk === 'LOW' ? 'adventurous' : risk === 'MODERATE' ? 'tense' : 'tense/dangerous', risk, setting, combat: 'NONE', structures: ['preparation changes what is available', 'logistics complication', 'adaptation and accountable payoff'], entry: ['accidental encounter'], rewards: ['Gear', 'Knowledge', 'coins'], outcomes: ['success/partial success', 'walk-away/refusal'] });
const make = (id: string, title: string, subtitle: string, hook: string, setting: string, risk: 'LOW' | 'MODERATE' | 'HIGH', startScene: string, scenes: Record<string, Scene>, activity?: string): Scenario =>
  largeAdventure(id, title, subtitle, fieldTags(hook, setting, risk, activity), startScene, scenes);
const gain = (id: string, provenance: string, flag: string) => ({ gainItems: [id], gainItemProvenance: { [id]: provenance }, historyFlags: [flag] });
const knowledge = (text: string) => ({ knowledge: [text] });

